def clean(df):
    df = df[df['body_mass_g'].notna()]
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df['sex'] = df['sex'].str.strip().str.lower()
    df = df[df['sex'].notna() & df['sex'].isin(['male', 'female'])]
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    return df

def answer(df):
    return {k: v for k, v in df.groupby('sex')['body_mass_g'].mean().items() if v is not None}
